   452	 * Taken from https://stackoverflow.com/a/9229821/9114791
   453	 */
   454	function uniqFast(items: string[]): string[] {
   455	    const seenItems: Record<string, number> = {};
   456	    const result: string[] = [];
   457	    let j = 0;
   458	
   459	    for (const item of items) {
   460	        if (seenItems[item] !== 1) {
   461	            seenItems[item] = 1;
   462	            result[j++] = item;
   463	        }
   464	    }
   465	
   466	    return result;
   467	}
